/bin/zsh -lc "python3 -c 'import csv,json
from pathlib import Path
p=Path(\"project\")
codes=json.loads((p/\"status-code-contract.json\").read_text())[\"status_codes\"]
live={}
for row in csv.DictReader((p/\"commits.csv\").open(newline=\"\")):
    if row[\"result\"]"'!="committed": continue
    key=row["key"]
    if row["operation"]=="delete": live.pop(key,None)
    else: live[key]=(row["incarnation"],int(row["revision"]),row["status_text"])
actual={row["key"]:(row["incarnation"],int(row["source_rev"]),int(row["status_code"]),int(row["mapped_rev"])) for row in csv.DictReader((p/"derived.csv").open(newline=""))}
expected={key:(inc,rev,codes[status],rev) for key,(inc,rev,status) in live.items()}
print("expected",json.dumps(expected,sort_keys=True))
print("actual",json.dumps(actual,sort_keys=True))
print("missing",sorted(set(expected)-set(actual)))
print("extra",sorted(set(actual)-set(expected)))
print("different",[(key,expected[key],actual[key]) for key in sorted(set(expected)&set(actual)) if expected[key]!=actual[key]])'"'"

